<section class="card"><div class="section-heading"><div><h2>Tài khoản nội bộ</h2><p class="muted">Phân quyền rõ ràng. Truy cập an toàn.</p></div><a class="button" href="#user-form">＋ Tạo tài khoản</a></div><div class="table-wrap"><table><thead><tr><th>Tài khoản</th><th>Họ tên</th><th>Phòng ban</th><th>Vai trò</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($list as $u): ?><tr><td class="mono"><?= e($u['username']) ?> <span class="badge"><?= e(strtoupper($u['auth_source'])) ?></span></td><td><?= e($u['ho_ten']) ?></td><td><?= e($u['ten_phong_ban']) ?></td><td><?php badge($u['role']) ?></td><td><?php badge($u['trang_thai']) ?></td><td><a class="button subtle" href="/admin/users?edit=<?= e($u['id']) ?>#user-form">Quản lý</a></td></tr><?php endforeach ?></tbody></table></div></section><div class="split-layout"><section class="card" id="user-form"><h2><?= $edit?'Cập nhật '.$edit['username']:'Tạo tài khoản' ?></h2><form method="post" class="form-stack"><?php csrf_field() ?><input type="hidden" name="action" value="<?= $edit?'update':'create' ?>"><?php if($edit): ?><input type="hidden" name="id" value="<?= e($edit['id']) ?>"><?php else: ?><?php field('username','Tên đăng nhập','','text',64); ?><label for="password">Mật khẩu tạm (12–72 byte)</label><input type="password" id="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required><?php endif ?><?php field('ho_ten','Họ tên',$edit['ho_ten']??'','text',150); field('email','Email',$edit['email']??'','email',190); field('so_may_le','Số máy lẻ',$edit['so_may_le']??'','text',20,false); select_field('phong_ban_id','Phòng ban',array_column(departments(),'ten_phong_ban','id'),$edit['phong_ban_id']??''); select_field('role','Vai trò',array_combine(['employee','accounting','hr','it_admin'],['Nhân viên','Kế toán','Nhân sự','Quản trị IT']),$edit['role']??'employee'); select_field('trang_thai','Trạng thái',['active'=>'Hoạt động','locked'=>'Đã khóa'],$edit['trang_thai']??'active'); ?><button id="save-user" class="button">Lưu tài khoản</button><?php if($edit): ?><a href="/admin/users">Hủy chỉnh sửa</a><?php endif ?></form></section><section class="card form-card"><h2>Bảo mật tài khoản</h2><p class="muted">Tài khoản mới hoặc được đặt lại mật khẩu bắt buộc đổi mật khẩu ở lần đăng nhập tiếp theo.</p><div class="tip-box">Không thể tự khóa, tự hạ quyền hoặc vô hiệu hóa quản trị IT cuối cùng.</div><?php if($edit): ?><h3>Đặt lại mật khẩu</h3><form method="post" class="form-stack" id="reset-password-form"><?php csrf_field() ?><input type="hidden" name="action" value="reset"><input type="hidden" name="id" value="<?= e($edit['id']) ?>"><label for="reset-password">Mật khẩu tạm mới (12–72 byte)</label><input id="reset-password" type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required><button id="reset-user-password" class="button danger">Đặt lại mật khẩu</button></form><?php endif ?></section></div>
